//! GV-17 pool vectors: `golden/expmisc/pool.json` (generated by `tools/golden/gen_expmisc.py` from the
//! Python `ReplayPool` with the task list, the commit analysis and the task create stubbed) must be
//! reproduced by the pool decisions and task shaping of `wg_experiments::pool`.

use std::error::Error;
use std::path::PathBuf;

use serde_json::{Map, Value, json};
use wg_experiments::pool::{
    Entry, ExistingIndex, ExistingReplay, POOL_TAG, REPLAY_TAG, Step, existing_index,
    replay_metadata, step, task_description, task_title,
};
use wg_experiments::replay::Features;

type TestResult = Result<(), Box<dyn Error>>;

fn load() -> Result<Vec<Value>, Box<dyn Error>> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../golden/expmisc/pool.json");
    let doc: Value = serde_json::from_str(&std::fs::read_to_string(path)?)?;
    Ok(doc["cases"]
        .as_array()
        .ok_or("cases is not an array")?
        .clone())
}

fn strings(value: &Value) -> Result<Vec<String>, Box<dyn Error>> {
    value
        .as_array()
        .ok_or("expected an array of strings")?
        .iter()
        .map(|item| {
            item.as_str()
                .map(str::to_owned)
                .ok_or_else(|| format!("not a string: {item}").into())
        })
        .collect()
}

fn argvs(value: &Value) -> Result<Vec<Vec<String>>, Box<dyn Error>> {
    value
        .as_array()
        .ok_or("expected an array of argv lists")?
        .iter()
        .map(strings)
        .collect()
}

/// `(key, sha, classifier)` of every task in the pages, in page order. The classifier defaults to
/// `replay-classifier-1` when the metadata has none, as the Python pool reads it.
type Entry3 = (String, Option<String>, String);

fn page_entries(pages: &Value) -> Result<Vec<Entry3>, Box<dyn Error>> {
    let mut entries = Vec::new();
    for page in pages.as_array().ok_or("pages is not an array")? {
        for task in page.as_array().ok_or("page is not an array")? {
            let replay = &task["metadata"]["replay"];
            let sha = replay["sha"].as_str().map(str::to_owned);
            let classifier = replay["classifier"]
                .as_str()
                .unwrap_or("replay-classifier-1")
                .to_owned();
            let key = task["key"].as_str().unwrap_or_default().to_owned();
            entries.push((key, sha, classifier));
        }
    }
    Ok(entries)
}

fn existing_from(entries: &[Entry3]) -> ExistingIndex {
    let refs: Vec<ExistingReplay> = entries
        .iter()
        .map(|(key, sha, classifier)| ExistingReplay {
            key,
            sha: sha.as_deref(),
            classifier,
        })
        .collect();
    existing_index(&refs)
}

fn features_of(value: &Value) -> Result<Features, Box<dyn Error>> {
    Ok(Features {
        src_lines: value["src_lines"].as_i64().ok_or("src_lines")?,
        test_lines: value["test_lines"].as_i64().ok_or("test_lines")?,
        src_files: value["src_files"].as_u64().ok_or("src_files")? as usize,
        test_files: value["test_files"].as_u64().ok_or("test_files")? as usize,
        packages: strings(&value["packages"])?,
        band: value["band"].as_u64().map(|b| b as u32),
    })
}

fn index_json(index: &ExistingIndex) -> Value {
    let found: Map<String, Value> = index
        .iter()
        .map(|(sha, key)| (sha.clone(), json!(key)))
        .collect();
    json!({ "index": found })
}

fn create_results(input: &Value, mut index: ExistingIndex) -> Result<Vec<Value>, Box<dyn Error>> {
    let mut created = 0usize;
    let mut results = Vec::new();
    for sha in strings(&input["shas"])? {
        let commit = input["commits"]
            .as_array()
            .and_then(|commits| commits.iter().find(|c| c["sha"] == json!(sha)))
            .ok_or("commit missing")?;
        let excluded = strings(&commit["excluded"])?;
        let excluded: Vec<&str> = excluded.iter().map(String::as_str).collect();
        let result = match step(&excluded, &sha, &index) {
            Step::Skipped { reason } => {
                json!({"sha": sha, "status": "skipped", "task_key": null, "reason": reason})
            }
            Step::Exists { task_key } => {
                json!({"sha": sha, "status": "exists", "task_key": task_key, "reason": null})
            }
            Step::Create => {
                // The Python stub numbers created tasks WG-1000, WG-1001, ...
                let key = format!("WG-{}", 1000 + created);
                created += 1;
                index = index.insert(sha.clone(), key.clone());
                json!({"sha": sha, "status": "created", "task_key": key, "reason": null})
            }
        };
        results.push(result);
    }
    Ok(results)
}

fn shaped_task(input: &Value) -> Result<Value, Box<dyn Error>> {
    let commit = &input["commit"];
    let sha = commit["sha"].as_str().unwrap_or_default();
    let subject = commit["subject"].as_str().unwrap_or_default();
    let body = commit["body"].as_str().unwrap_or_default();
    let base_ref = input["base_ref"].as_str().unwrap_or_default();
    let test_paths = strings(&commit["test_paths"])?;
    let source_paths = strings(&commit["source_paths"])?;
    let oracle = argvs(&commit["oracle"])?;
    let features = features_of(&commit["features"])?;
    // The shell supplies the validation time; the generator pins it to the same instant.
    let validation: Option<(Vec<i64>, Vec<i64>)> = match &input["validation"] {
        Value::Null => None,
        v => Some((
            v["base"]
                .as_array()
                .into_iter()
                .flatten()
                .filter_map(Value::as_i64)
                .collect(),
            v["solution"]
                .as_array()
                .into_iter()
                .flatten()
                .filter_map(Value::as_i64)
                .collect(),
        )),
    };
    let validated_at = validation.as_ref().map(|_| "2026-10-26T00:00:00+00:00");
    let entry = Entry {
        sha,
        parent: commit["parent"].as_str(),
        base_ref,
        test_paths: &test_paths,
        source_paths: &source_paths,
        oracle: &oracle,
        features: &features,
        validation: validation
            .as_ref()
            .map(|(base, solution)| (base.as_slice(), solution.as_slice())),
        validated_at,
    };
    Ok(json!({
        "title": task_title(sha, subject),
        "description": task_description(sha, subject, body, &test_paths, &oracle, base_ref),
        "tags": [REPLAY_TAG, POOL_TAG],
        "metadata": replay_metadata(&entry),
    }))
}

#[test]
fn pool_vectors() -> TestResult {
    let mut failures = Vec::new();
    for case in load()? {
        let id = case["id"].as_str().unwrap_or_default().to_owned();
        let input = &case["input"];
        let actual = if id.starts_with("index-") {
            index_json(&existing_from(&page_entries(&input["pages"])?))
        } else if id.starts_with("create-") {
            let index = existing_from(&page_entries(&input["pages"])?);
            json!({ "results": create_results(input, index)? })
        } else if id.starts_with("task-") {
            shaped_task(input)?
        } else {
            failures.push(format!("{id}: no case handler"));
            continue;
        };
        if actual != case["output"] {
            failures.push(format!("{id}: got {actual}, want {}", case["output"]));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    Ok(())
}
